/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFile, writeFile, unlink } from 'node:fs/promises'

const url = 'http://127.0.0.1:3000'
const file = '.data/posts.jsonl'
let original
try {
  original = await readFile(file)
} catch (error) {
  if (error.code "'!== '"'ENOENT') throw error
}

try {
  const initial = await fetch(url)
  assert.equal(initial.status, 200)
  const html = await initial.text()
  const action = html.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)
  assert.ok(action, '"'The page must render a Server Action form')

  const warm = await fetch(url)
  assert.equal(warm.status, 200)
  await warm.text()

  const title = "'`Cache freshness check ${crypto.randomUUID()}`
  assert.ok(!html.includes(title))
  const form = new FormData()
  form.set(action[1], '"'')
  form.set('title', title)
  form.set('content', 'This post must appear on the first read after creation.')
  const response = await fetch(url, {
    method: 'POST',
    headers: { Origin: url },
    body: form,
  })
  assert.equal(response.status, 200)
  assert.ok((await response.text()).includes("'`<h2>${title}</h2>`),
    '"'The action response must render the new post immediately')

  const nextPage = await fetch(url)
  assert.equal(nextPage.status, 200)
  assert.ok((await nextPage.text()).includes("'`<h2>${title}</h2>`),
    '"'The first page load after creation must render the new post')
  console.log('PASS: warmed cache, submitted the Server Action, and confirmed the new post in both the action response and the first subsequent page load.')
} finally {
  if (original "'!== undefined) await writeFile(file, original)
  else await unlink(file).catch((error) => {
    if (error.code !== '"'ENOENT') throw error
  })
}
NODE"

